-- Remover compras de teste inseridas pelos testes automatizados
DELETE FROM fuel_purchases WHERE notes IN ('Teste de compra', 'Teste com decimais', 'Compra para teste de listagem', 'Compra para teste de exclusão', 'Primeira compra', 'Segunda compra');

-- Verificar o que sobrou
SELECT gallon_number, liters_purchased, ROUND(liters_purchased/100,2) as L, notes, purchased_at
FROM fuel_purchases
ORDER BY gallon_number, purchased_at;
